import { Avatar, Box, Button, Container, Dialog, DialogActions, DialogContent, DialogTitle, Grid, Paper, TextField, Typography } from '@mui/material';
import { getAuth, sendPasswordResetEmail, signOut } from 'firebase/auth';
import { collection, getDocs, getFirestore, query, updateDoc, where } from 'firebase/firestore';
import { getDownloadURL, getStorage, ref, uploadBytes } from 'firebase/storage';
import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

export default function Logout() {
  const navigate = useNavigate();
  const auth = getAuth();
  const [teacher, setTeacher] = useState(null);
  const [email, setEmail] = useState('');
  const [profilePicUrl, setProfilePicUrl] = useState('');
  const [resetStatus, setResetStatus] = useState('');
  const [isResetting, setIsResetting] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [newName, setNewName] = useState('');
  const [newProfilePic, setNewProfilePic] = useState(null);
  const firestore = getFirestore();
  const storage = getStorage();

  useEffect(() => {
    const fetchTeacherData = async () => {
      try {
        const currentUser = auth.currentUser;
        if (currentUser) {
          setEmail(currentUser.email); // Store the user's email
          const teacherQuery = query(
            collection(firestore, 'Teachers'),
            where('id', '==', currentUser.uid)
          );
          const teacherSnapshot = await getDocs(teacherQuery);
          const teacherData = teacherSnapshot.docs[0]?.data();
          setTeacher(teacherData);
          setProfilePicUrl(teacherData.image || 'default-avatar-url'); // Set profile picture URL
        }
      } catch (error) {
        console.error('Error fetching teacher data:', error);
      }
    };

    fetchTeacherData();
  }, [auth, firestore]);

  const handleChangePassword = async () => {
    if (!email) return;

    setIsResetting(true);
    setResetStatus('');

    try {
      await sendPasswordResetEmail(auth, email);
      setResetStatus('A password reset link has been sent to your email.');
    } catch (error) {
      setResetStatus('Error sending password reset email. Please try again.');
    } finally {
      setIsResetting(false);
    }
  };

  const handleLogout = () => {
    signOut(auth)
      .then(() => {
        console.log('Logout successful');
        navigate('/'); // Redirect to home page after logout
      })
      .catch((error) => {
        console.error('Logout error:', error);
      });
  };

  const handleOpenEditModal = () => {
    setNewName(teacher?.name || '');
    setIsEditing(true);
  };

  const handleCloseEditModal = () => {
    setIsEditing(false);
  };

  const handleProfilePicChange = (e) => {
    setNewProfilePic(e.target.files[0]);
  };

  const handleSaveChanges = async () => {
    try {
      // Query the Firestore collection to find the teacher's document
      const teacherQuery = query(
        collection(firestore, 'Teachers'),
        where('id', '==', auth.currentUser.uid)
      );
      
      const teacherSnapshot = await getDocs(teacherQuery);
  
      if (!teacherSnapshot.empty) {
        const teacherDoc = teacherSnapshot.docs[0].ref; // Get the document reference
        const updatedData = {
          name: newName,
        };
  
        // Upload new profile picture if selected
        if (newProfilePic) {
          const storageRef = ref(storage, `profile_pics/${auth.currentUser.uid}`);
          await uploadBytes(storageRef, newProfilePic);
          const downloadUrl = await getDownloadURL(storageRef);
          updatedData.image = downloadUrl;
          setProfilePicUrl(downloadUrl); // Update profile picture URL in the UI
        }
  
        // Update the Firestore document
        await updateDoc(teacherDoc, updatedData);
  
        // Update local state
        setTeacher((prev) => ({ ...prev, ...updatedData }));
        setIsEditing(false);
      } else {
        console.error('No teacher document found for the current user.');
      }
    } catch (error) {
      console.error('Error updating teacher data:', error);
    }
  };
  

  return (
    <Container maxWidth="md" sx={{ mt: 4, mb: 4 }}>
      <Paper elevation={3} sx={{ p: 3 }}>
        <Box sx={{ textAlign: 'center', mb: 4 }}>
          <Typography variant="h4" gutterBottom>
            HOHOE E.P BASIC "A" SCHOOL
          </Typography>
          <Typography variant="body1" color="textSecondary">
            Address: P.O.BOX 2, Hohoe, Ghana, VC-0003-7066
          </Typography>
          <Typography variant="body1" color="textSecondary">
            Phone: (233) 2080-783-861
          </Typography>
        </Box>

        {teacher && (
          <Box sx={{ mb: 4 }}>
            <Typography variant="h5" gutterBottom>
              Teacher Information
            </Typography>
            <Paper elevation={2} sx={{ p: 2, mb: 2 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                <Avatar src={profilePicUrl} alt="Profile Picture" sx={{ width: 80, height: 80, mr: 2 }} />
                <Box>
                  <Typography variant="h6">Name: {teacher.name}</Typography>
                  <Typography variant="body1">Email: {teacher.email}</Typography>
                  <Typography variant="body1">Classes: {teacher.classes?.join(', ')}</Typography>
                  <Typography variant="body1">Subjects: {teacher.subjects?.join(', ')}</Typography>
                </Box>
              </Box>
            </Paper>
          </Box>
        )}

        {resetStatus && (
          <Box sx={{ mb: 2, textAlign: 'center' }}>
            <Typography variant="body1" color={resetStatus.includes('Error') ? 'error' : 'success'}>
              {resetStatus}
            </Typography>
          </Box>
        )}

        <Grid container spacing={2}>
          <Grid item xs={12} md={6}>
            <Button
              variant="contained"
              color="primary"
              fullWidth
              onClick={handleChangePassword}
              disabled={isResetting}
            >
              {isResetting ? 'Sending...' : 'Change/Reset Password'}
            </Button>
          </Grid>
          <Grid item xs={12} md={6}>
            <Button
              variant="outlined"
              color="secondary"
              fullWidth
              onClick={handleLogout}
            >
              Logout
            </Button>
          </Grid>
        </Grid>

        <Box sx={{ textAlign: 'center', mt: 4 }}>
          <Button variant="outlined" onClick={handleOpenEditModal}>
            Edit Profile
          </Button>
        </Box>
      </Paper>

      {/* Edit Profile Modal */}
      <Dialog open={isEditing} onClose={handleCloseEditModal}>
        <DialogTitle>Edit Profile</DialogTitle>
        <DialogContent>
          <TextField
            margin="dense"
            label="Name"
            fullWidth
            value={newName}
            onChange={(e) => setNewName(e.target.value)}
          />
          <input
            type="file"
            accept="image/*"
            onChange={handleProfilePicChange}
            style={{ marginTop: '16px' }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseEditModal} color="primary">
            Cancel
          </Button>
          <Button onClick={handleSaveChanges} color="primary">
            Save Changes
          </Button>
        </DialogActions>
      </Dialog>
    </Container>
  );
}
