import { Box, Card, CardContent, CardMedia, Container, Grid, Paper, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Typography } from '@mui/material';
import { styled } from '@mui/material/styles';
import { getAuth } from 'firebase/auth';
import { collection, getDocs, getFirestore, query, where } from 'firebase/firestore';
import React, { useEffect, useState } from 'react';

const CardStyled = styled(Card)(({ theme }) => ({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  padding: theme.spacing(2),
}));

const imageUrls = {
  total: 'https://firebasestorage.googleapis.com/v0/b/hohoe-epa.appspot.com/o/Total.png?alt=media&token=31c59d0a-009d-4dd7-8b79-d0ea3275540a',
  male: 'https://firebasestorage.googleapis.com/v0/b/hohoe-epa.appspot.com/o/boys.png?alt=media&token=c86c707b-65ba-412c-988a-e93775a25686',
  female: 'https://firebasestorage.googleapis.com/v0/b/hohoe-epa.appspot.com/o/girls.png?alt=media&token=c49a6b64-bc67-4474-aca1-1306ac53cdb0'
};

export default function Home() {
  const [teacher, setTeacher] = useState(null);
  const [students, setStudents] = useState([]);
  const [totals, setTotals] = useState({ male: 0, female: 0, total: 0 });
  const firestore = getFirestore();
  const currentUser = getAuth().currentUser;

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Fetch the current teacher's data
        const teacherQuery = query(collection(firestore, 'Teachers'), where('id', '==', currentUser.uid ));
        const teacherSnapshot = await getDocs(teacherQuery);
        const teacherData = teacherSnapshot.docs[0]?.data();
        setTeacher(teacherData);

        if (teacherData) {
          const classesToQuery = teacherData.classes || [];
          console.log(classesToQuery);

          // Fetch students for the classes the teacher teaches
          const studentQuery = query(
            collection(firestore, 'Students'),
            where('classLevel', 'in', classesToQuery)
          );
          const studentSnapshot = await getDocs(studentQuery);
          const studentData = studentSnapshot.docs.map(doc => doc.data());
          console.log("Student Data", studentData);
          setStudents(studentData);

          // Calculate totals
          const calculatedTotals = studentData.reduce((acc, student) => {
            acc.male += student.sex === 'Male' ? 1 : 0;
            acc.female += student.sex === 'Female' ? 1 : 0;
            acc.total += 1;
            return acc;
          }, { male: 0, female: 0, total: 0 });

          setTotals(calculatedTotals);
        }
      } catch (error) {
        console.error("Error fetching data: ", error);
      }
    };

    fetchData();
  }, [currentUser.uid, firestore]);

  if (!teacher) {
    return <Typography>Loading...</Typography>;
  }

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Grid container spacing={3}>
        {/* Cards for totals */}
        {['Total Students', 'Male', 'Female'].map((card, index) => (
          <Grid item xs={12} md={4} key={index}>
            <CardStyled>
              <CardMedia
                component="img"
                height="140"
                image={imageUrls[card.toLowerCase().replace(' ', '')]}
                alt={card}
              />
              <CardContent>
                <Typography variant="h4">{card}</Typography>
                <Typography variant="h6">
                  {card === 'Total Students' ? totals.total : card === 'Male' ? totals.male : totals.female}
                </Typography>
              </CardContent>
            </CardStyled>
          </Grid>
        ))}
      </Grid>

      {/* Table for students */}
      <Box sx={{ mt: 4 }}>
        <Paper>
          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Name</TableCell>
                  <TableCell align="right">Class</TableCell>
                  <TableCell align="right">Gender</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {students.map((student) => (
                  <TableRow key={student.code}>
                    <TableCell component="th" scope="row">
                      {student.name}
                    </TableCell>
                    <TableCell align="right">{student.classLevel}</TableCell>
                    <TableCell align="right">{student.sex}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
      </Box>
    </Container>
  );
}
