import {
  Alert,
  Box,
  Button,
  CircularProgress,
  Container,
  FormControl,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Snackbar,
  TextField,
  Typography
} from '@mui/material';
import { getAuth } from 'firebase/auth';
import { collection, doc, getDocs, getFirestore, query, updateDoc, where } from 'firebase/firestore';
import * as React from 'react';
import { useLocation, useNavigate, useParams } from 'react-router-dom';

const calculateGrade = (total, classLevel) => {
  if (['Basic 7', 'Basic 8', 'Basic 9'].includes(classLevel)) {
    if (total >= 80) return { grade: 1, remark: 'Excellent' };
    if (total >= 70) return { grade: 2, remark: 'Very Good' };
    if (total >= 65) return { grade: 3, remark: 'Good' };
    if (total >= 60) return { grade: 4, remark: 'Credit' };
    if (total >= 55) return { grade: 5, remark: 'Credit' };
    if (total >= 50) return { grade: 6, remark: 'Credit' };
    if (total >= 45) return { grade: 7, remark: 'Pass' };
    if (total >= 40) return { grade: 8, remark: 'Pass' };
    return { grade: 9, remark: 'Fail' };
  } else {
    if (total >= 80) return { grade: 'HP', remark: 'High Proficient' };
    if (total >= 68) return { grade: 'P', remark: 'Proficient' };
    if (total >= 54) return { grade: 'AP', remark: 'Approaching Proficiency' };
    if (total >= 40) return { grade: 'D', remark: 'Developing' };
    return { grade: 'E', remark: 'Emerging' };
  }
};

export default function AddGrades() {
  const { className, studentName } = useParams();
  const location = useLocation();
  const student = location.state?.student;
  const navigate = useNavigate();

  const currentUser = getAuth().currentUser; // Get the current user
  const [teacherSubjects, setTeacherSubjects] = React.useState([]);
  const [subject, setSubject] = React.useState('');
  const [classScore, setClassScore] = React.useState('');
  const [examScore, setExamScore] = React.useState('');
  const [total, setTotal] = React.useState(null);
  const [grade, setGrade] = React.useState(null);
  const [remark, setRemark] = React.useState('');
  const [selectedTerm, setSelectedTerm] = React.useState('Term 1');
  const [selectedYear, setSelectedYear] = React.useState(`${new Date().getFullYear()}-${new Date().getFullYear() + 1}`);
  const [loading, setLoading] = React.useState(false);
  const [success, setSuccess] = React.useState(false);
  const [saveError, setSaveError] = React.useState('');

  const terms = ['Term 1', 'Term 2', 'Term 3'];
  const years = Array.from(new Array(10), (val, index) => {
    const startYear = new Date().getFullYear() + index;
    const endYear = startYear + 1;
    return `${startYear}-${endYear}`;
  });

  React.useEffect(() => {
    const fetchTeacherSubjects = async () => {
      if (currentUser) {
        const db = getFirestore();
        const q = query(collection(db, 'Teachers'), where('id', '==', currentUser.uid));
        const querySnapshot = await getDocs(q);

        querySnapshot.forEach((doc) => {
          const teacherData = doc.data();
          console.log("This is the teacher data", teacherData)
          setTeacherSubjects(teacherData.subjects || []);
        });
      }
    };

    fetchTeacherSubjects();
  }, [currentUser]);

  const handleAddGrade = async () => {
    const classScoreNum = parseFloat(classScore);
    const examScoreNum = parseFloat(examScore);
    if (isNaN(classScoreNum) || isNaN(examScoreNum)) {
      alert('Please enter valid scores');
      return;
    }
    const totalScore = classScoreNum + examScoreNum;

    // Check if the total score exceeds 100
    if (totalScore > 100) {
      setSaveError('Total score cannot exceed 100');
      return;
    }

    const gradeInfo = calculateGrade(totalScore, student.classLevel);
    setTotal(totalScore);
    setGrade(gradeInfo.grade);
    setRemark(gradeInfo.remark);

    setLoading(true);
    try {
      const db = getFirestore();
      const studentRef = doc(db, 'Students', student.id);

      await updateDoc(studentRef, {
        [`grades.${selectedYear}.${selectedTerm}.${subject}.classScore`]: classScoreNum,
        [`grades.${selectedYear}.${selectedTerm}.${subject}.examScore`]: examScoreNum,
        [`grades.${selectedYear}.${selectedTerm}.${subject}.totalScore`]: totalScore,
        [`grades.${selectedYear}.${selectedTerm}.${subject}.grade`]: gradeInfo.grade,
        [`grades.${selectedYear}.${selectedTerm}.${subject}.remark`]: gradeInfo.remark
      });

      setSuccess(true);
    } catch (err) {
      setSaveError('Error saving grade: ' + (err.message || 'Unknown error'));
    } finally {
      setLoading(false);
    }
  };
  if (!student) {
    return (
      <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
        <Typography variant="h4">Add Grades</Typography>
        <Typography variant="body1">No student data available.</Typography>
      </Container>
    );
  }

  return (
    <Container maxWidth="md" sx={{ mt: 4, mb: 4 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 4 }}>
        <Typography variant="h4">
          Add Grades for {student.name}
        </Typography>
        <FormControl sx={{ minWidth: 120 }}>
          <InputLabel id="term-select-label">Term</InputLabel>
          <Select
            labelId="term-select-label"
            id="term-select"
            value={selectedTerm}
            onChange={(e) => setSelectedTerm(e.target.value)}
            label="Term"
          >
            {terms.map((term) => (
              <MenuItem key={term} value={term}>{term}</MenuItem>
            ))}
          </Select>
        </FormControl>
        <FormControl sx={{ minWidth: 120 }}>
          <InputLabel id="year-select-label">Year</InputLabel>
          <Select
            labelId="year-select-label"
            id="year-select"
            value={selectedYear}
            onChange={(e) => setSelectedYear(e.target.value)}
            label="Year"
          >
            {years.map((year) => (
              <MenuItem key={year} value={year}>{year}</MenuItem>
            ))}
          </Select>
        </FormControl>
      </Box>
      <FormControl fullWidth sx={{ mb: 4 }}>
        <InputLabel id="subject-select-label">Subject</InputLabel>
        <Select
          labelId="subject-select-label"
          id="subject-select"
          value={subject}
          onChange={(e) => setSubject(e.target.value)}
          label="Subject"
        >
          {teacherSubjects.map((subject) => (
            <MenuItem key={subject} value={subject}>{subject}</MenuItem>
          ))}
        </Select>
      </FormControl>
      <TextField
        fullWidth
        label="Class Score (out of 50)"
        type="number"
        value={classScore}
        onChange={(e) => setClassScore(e.target.value)}
        sx={{ mb: 4 }}
      />
      <TextField
        fullWidth
        label="Exam Score (out of 50)"
        type="number"
        value={examScore}
        onChange={(e) => setExamScore(e.target.value)}
        sx={{ mb: 4 }}
      />
      <Button
        variant="contained"
        color="primary"
        onClick={handleAddGrade}
        disabled={loading}
      >
        {loading ? <CircularProgress size={24} /> : 'Add Grade'}
      </Button>
      {saveError && (
        <Typography variant="body1" color="error" sx={{ mt: 2 }}>
          {saveError}
        </Typography>
      )}
      {success && (
        <Snackbar open={success} autoHideDuration={6000} onClose={() => setSuccess(false)}>
          <Alert onClose={() => setSuccess(false)} severity="success">
            Grade added successfully!
          </Alert>
        </Snackbar>
      )}
      {total !== null && grade !== null && (
        <Paper sx={{ mt: 4, p: 2 }}>
          <Typography variant="h6">Grade Details</Typography>
          <Typography><strong>Year:</strong> {selectedYear}</Typography>
          <Typography><strong>Term:</strong> {selectedTerm}</Typography>
          <Typography><strong>Subject:</strong> {subject}</Typography>
          <Typography><strong>Total Score:</strong> {total}</Typography>
          <Typography><strong>Grade:</strong> {grade}</Typography>
          <Typography><strong>Remark:</strong> {remark}</Typography>
        </Paper>
      )}
    </Container>
  );
}
