import { Box, Button, Container, Divider, TextField, Typography } from '@mui/material';
import { collection, getDocs, getFirestore, query, where } from 'firebase/firestore';
import * as React from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import './ClassDetailStyles.css'; // Import the external style file

export default function ClassDetail() {
  const { className } = useParams();
  const navigate = useNavigate();
  const [searchTerm, setSearchTerm] = React.useState('');
  const [students, setStudents] = React.useState([]);
  const [filteredStudents, setFilteredStudents] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState('');
    // Helper function to calculate age
    const calculateAge = (dob) => {
      const birthDate = new Date(dob);
      const today = new Date();
      let age = today.getFullYear() - birthDate.getFullYear();
      const monthDifference = today.getMonth() - birthDate.getMonth();
  
      if (monthDifference < 0 || (monthDifference === 0 && today.getDate() < birthDate.getDate())) {
        age--;
      }
      return age;
    };

  React.useEffect(() => {
    const fetchStudents = async () => {
      try {
        const db = getFirestore();
        const studentsRef = collection(db, 'Students');
        const q = query(studentsRef, where('classLevel', '==', className));
        const querySnapshot = await getDocs(q);

        if (!querySnapshot.empty) {
          const studentsData = querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
          setStudents(studentsData);
          setFilteredStudents(studentsData);
        } else {
          setError('No students found for this class');
        }
      } catch (err) {
        setError('Error fetching students: ' + (err.message || 'Unknown error'));
      } finally {
        setLoading(false);
      }
    };

    fetchStudents();
  }, [className]);

  React.useEffect(() => {
    setFilteredStudents(
      students.filter(student =>
        student.name.toLowerCase().includes(searchTerm.toLowerCase())
      )
    );
  }, [searchTerm, students]);

  const handleViewDetails = (student) => {
    const encodedName = encodeURIComponent(student.name);
    navigate(`details/${encodedName}`, { state: { student } });
  };

  const handleViewGrades = (student) => {
    const encodedName = encodeURIComponent(student.name);
    console.log(student)
    navigate(`grades/${encodedName}`, { state: { student,code: student.code,term: student.term  } });
  };
  console.log("name", className)
  const handleClassSummary = () => {
    console.log("name", className)
   navigate("summary", { state: { classLevel: className } });
  };
  if (loading) {
    return (
      <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
        <Typography variant="h4">Loading...</Typography>
      </Container>
    );
  }

  if (error) {
    return (
      <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
        <Typography variant="h4" color="error">{error}</Typography>
      </Container>
    );
  }

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Students in {className}
      </Typography>
      <TextField
        variant="outlined"
        placeholder="Search by name"
        fullWidth
        sx={{ mb: 4 }}
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />
      <div className="student-list">
        {filteredStudents.map((student) => (
          <div className="student-item" key={student.id}>
            <img
              className="student-image"
              src={student.image}
              alt={student.name}
            />
            <div className="student-content">
              <Typography variant="h6">{student.name}</Typography>
              <Typography variant="body2" color="textSecondary">
                Age:  {calculateAge(student.dob)}
              </Typography>
              <Typography variant="body2" color="textSecondary">
                Date of Birth: {new Date(student.dob).toLocaleDateString()}
              </Typography>
              <Typography variant="body2" color="textSecondary">
                Contact: {student.contact}
              </Typography>
              <Divider sx={{ my: 2 }} />
            </div>
            <div className="student-buttons">
              <Button 
                variant="contained" 
                color="primary"
                onClick={() => handleViewDetails(student)}
              >
                View More Details
              </Button>
              <Button variant="contained" color="secondary" onClick={() => handleViewGrades(student)}>
                View Grades
              </Button>
            </div>
          </div>
        ))}
      </div>
      <Box sx={{ position: 'fixed', bottom: 16, right: 16 }}>
        <Button 
          variant="contained" 
          color="primary" 
          onClick={handleClassSummary}
        >
          Class Summary
        </Button>
      </Box>
    </Container>
  );
}
