import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import {
  Autocomplete,
  Box,
  Button,
  Card,
  CardContent,
  CardMedia,
  Checkbox,
  Container,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  FormControlLabel,
  Grid,
  TextField,
  Typography
} from '@mui/material';
import { deleteUser as deleteAuthUser, getAuth } from 'firebase/auth';
import { collection, deleteDoc, doc, getDocs, getFirestore, query, updateDoc, where } from 'firebase/firestore';
import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

const classesOptions = ['KG 1', 'KG 2', 'Basic 1', 'Basic 2', 'Basic 3', 'Basic 4', 'Basic 5', 'Basic 6', 'Basic 7', 'Basic 8', 'Basic 9'];
const subjectsOptions = ['Mathematics','Literacy','Language', 'Integrated Science','Numeracy', 'English Language', 'History', 'Creative Art', 'Owop', 'BDT', 'French','RME', 'Ewe', 'Career Tech.', 'Social Studies', 'Computing'];

export default function Teachers() {
  const [teachers, setTeachers] = useState([]);
  const [openDelete, setOpenDelete] = useState(false);
  const [openEdit, setOpenEdit] = useState(false);
  const [selectedTeacher, setSelectedTeacher] = useState(null);
  const [selectedClass, setSelectedClass] = useState(''); // For class teacher selection
  const navigate = useNavigate();
  const firestore = getFirestore();

  useEffect(() => {
    const fetchTeachers = async () => {
      try {
        const q = query(collection(firestore, 'Teachers'));
        const querySnapshot = await getDocs(q);
        const teachersList = querySnapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data(),
          classes: doc.data().classes || [],  // Ensure classes is always an array
          subjects: doc.data().subjects || [] // Ensure subjects is always an array
        }));
        setTeachers(teachersList);
      } catch (error) {
        console.error('Error fetching teachers:', error);
      }
    };

    fetchTeachers();
  }, [firestore]);

  const handleOpenDelete = (teacher) => {
    setSelectedTeacher(teacher);
    setOpenDelete(true);
  };

  const handleCloseDelete = () => {
    setOpenDelete(false);
    setSelectedTeacher(null);
  };



  const handleConfirmDelete = async () => {
    try {
      const teachersRef = collection(firestore, 'Teachers');
  
      // Query to find the teacher by ID in Firestore
      const q = query(teachersRef, where('id', '==', selectedTeacher.id));
      const querySnapshot = await getDocs(q);
  
      // Check if the teacher exists in Firestore
      if (!querySnapshot.empty) {
        const teacherDoc = querySnapshot.docs[0]; // Get the first matching document
        const teacherData = teacherDoc.data(); // Get teacher's data from Firestore
  
        // Optional: Check if the teacher has an authUid stored in Firestore
        const authUid = teacherData.id; // Assuming you're storing the auth UID
        
        // Delete the teacher document from Firestore
        await deleteDoc(doc(firestore, 'Teachers', teacherDoc.id));
  
        // If the teacher has an associated Firebase Auth user, delete them from Firebase Auth
        if (authUid) {
          const auth = getAuth();
          const user = auth.currentUser; // Current authenticated user (or admin in privileged apps)
  
          // Check if the current authenticated user matches the teacher’s authUid (for admin use only)
          if (user && user.uid === authUid) {
            await deleteAuthUser(user); // Delete the Firebase Auth user
            console.log('User account deleted from Firebase Authentication');
          } else {
            console.error('Unable to delete user from Firebase Authentication. AuthUid mismatch or insufficient permissions.');
          }
        }
  
        // Remove the teacher from the local state
        setTeachers(teachers.filter((teacher) => teacher.id !== selectedTeacher.id));
        
        handleCloseDelete(); // Close the modal after deletion
      } else {
        console.error('No teacher found with the specified ID.');
      }
    } catch (error) {
      console.error('Error deleting teacher:', error);
    }
  };
  
  

  const handleOpenEdit = (teacher) => {
    setSelectedTeacher(teacher);
    setSelectedClass(teacher.classTeacher || ''); // Set the selected class if class teacher
    setOpenEdit(true);
  };

  const handleCloseEdit = () => {
    setOpenEdit(false);
    setSelectedTeacher(null);
    setSelectedClass('');
  };

  const handleEditChange = (e) => {
    const { name, value } = e.target;
    setSelectedTeacher({ ...selectedTeacher, [name]: value });
  };

  const handleClassesChange = (event, newValue) => {
    setSelectedTeacher({ ...selectedTeacher, classes: newValue });
  };

  const handleSubjectsChange = (event, newValue) => {
    setSelectedTeacher({ ...selectedTeacher, subjects: newValue });
  };

  const handleClassTeacherChange = (event) => {
    if (event.target.checked) {
      setSelectedTeacher({ ...selectedTeacher, isClassTeacher: true });
    } else {
      setSelectedTeacher({ ...selectedTeacher, isClassTeacher: false });
    }
  };

  const handleClassSelectionChange = (event) => {
    setSelectedClass(event.target.value);
  };

  const handleSaveEdit = async () => {
    if (!selectedTeacher?.id) {
      console.error('No teacher ID found.');
      return;
    }
  
    try {
      const teachersRef = collection(firestore, 'Teachers');
      const q = query(teachersRef, where('id', '==', selectedTeacher.id));
      
      // Fetch documents that match the query
      const querySnapshot = await getDocs(q);
      if (querySnapshot.empty) {
        console.error('No document found with ID:', selectedTeacher.id);
        return;
      }
  
      // Document exists, proceed with update
      const teacherDoc = querySnapshot.docs[0]; // Get the first document from the query results
      const teacherRef = doc(firestore, 'Teachers', teacherDoc.id);
  
      await updateDoc(teacherRef, {
        name: selectedTeacher.name,
        staffId: selectedTeacher.staffId,
        classes: selectedTeacher.classes,
        subjects: selectedTeacher.subjects,
        isClassTeacher: selectedTeacher.isClassTeacher || false,
        classTeacher: selectedTeacher.isClassTeacher ? selectedClass : '' // Store selected class if class teacher
      });
  
      setTeachers(
        teachers.map((teacher) => (teacher.id === selectedTeacher.id ? selectedTeacher : teacher))
      );
      handleCloseEdit();
    } catch (error) {
      console.error('Error updating teacher:', error);
    }
  };
  
  const handleAddTeacher = () => {
    navigate('addteacher');
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Teachers
      </Typography>
      <Grid container spacing={4}>
        {teachers.map((teacher) => (
          <Grid item xs={12} sm={6} md={4} key={teacher.id}>
            <Card sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
              <CardMedia
                component="img"
                image={teacher.image || 'https://via.placeholder.com/100'}
                alt={teacher.name}
                sx={{ width: '100%', height: 200 }}
              />
              <CardContent sx={{ flexGrow: 1 }}>
                <Typography variant="h6" gutterBottom>
                  {teacher.name}
                </Typography>
                <Typography variant="body2" color="textSecondary">
                  Staff ID: {teacher.staffId}
                </Typography>
                <Typography variant="body2" color="textSecondary">
                  Classes: {(teacher.classes || []).join(', ')}
                </Typography>
                <Typography variant="body2" color="textSecondary">
                  Subjects: {(teacher.subjects || []).join(', ')}
                </Typography>
                {teacher.isClassTeacher && (
                  <Typography variant="body2" color="textSecondary">
                    Class Teacher for: {teacher.classTeacher}
                  </Typography>
                )}
                <Grid container spacing={1} sx={{ mt: 2 }}>
                  <Grid item xs={6}>
                    <Button
                      variant="outlined"
                      color="error"
                      fullWidth
                      startIcon={<DeleteIcon />}
                      onClick={() => handleOpenDelete(teacher)}
                    >
                      Delete
                    </Button>
                  </Grid>
                  <Grid item xs={6}>
                    <Button
                      variant="outlined"
                      color="primary"
                      fullWidth
                      endIcon={<EditIcon />}
                      onClick={() => handleOpenEdit(teacher)}
                    >
                      Edit
                    </Button>
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
      <Box sx={{ position: 'fixed', bottom: 16, right: 16 }}>
        <Button variant="contained" color="primary" onClick={handleAddTeacher}>
          Add Teacher
        </Button>
      </Box>

      {/* Delete Confirmation Modal */}
      <Dialog open={openDelete} onClose={handleCloseDelete}>
        <DialogTitle>Confirm Delete</DialogTitle>
        <DialogContent>
          <DialogContentText>
            Are you sure you want to delete {selectedTeacher?.name}?
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDelete} color="primary">
            Cancel
          </Button>
          <Button onClick={handleConfirmDelete} color="error">
            Delete
          </Button>
        </DialogActions>
      </Dialog>

      {/* Edit Teacher Modal */}
      <Dialog open={openEdit} onClose={handleCloseEdit}>
        <DialogTitle>Edit Teacher</DialogTitle>
        <DialogContent>
          <TextField
            autoFocus
            margin="dense"
            name="name"
            label="Name"
            type="text"
            fullWidth
            value={selectedTeacher?.name || ''}
            onChange={handleEditChange}
          />
          <TextField
            margin="dense"
            name="staffId"
            label="Staff ID"
            type="text"
            fullWidth
            value={selectedTeacher?.staffId || ''}
            onChange={handleEditChange}
          />
          <Autocomplete
            multiple
            options={classesOptions}
            getOptionLabel={(option) => option}
            value={selectedTeacher?.classes || []}
            onChange={handleClassesChange}
            renderInput={(params) => (
              <TextField
                {...params}
                margin="dense"
                label="Classes"
                fullWidth
              />
            )}
            sx={{ mb: 2 }}
          />
          <Autocomplete
            multiple
            options={subjectsOptions}
            getOptionLabel={(option) => option}
            value={selectedTeacher?.subjects || []}
            onChange={handleSubjectsChange}
            renderInput={(params) => (
              <TextField
                {...params}
                margin="dense"
                label="Subjects"
                placeholder="Select subjects"
                fullWidth
              />
            )}
            sx={{ mb: 2 }}
          />
          <FormControlLabel
            control={
              <Checkbox
                checked={selectedTeacher?.isClassTeacher || false}
                onChange={handleClassTeacherChange}
              />
            }
            label="Class Teacher"
          />
          {selectedTeacher?.isClassTeacher && (
            <TextField
              margin="dense"
              label="Select Class"
              select
              fullWidth
              value={selectedClass}
              onChange={handleClassSelectionChange}
              SelectProps={{ native: true }}
              sx={{ mb: 2 }}
            >
              <option value="">Select class</option>
              {classesOptions.map((option) => (
                <option key={option} value={option}>
                  {option}
                </option>
              ))}
            </TextField>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseEdit} color="primary">
            Cancel
          </Button>
          <Button onClick={handleSaveEdit} color="primary">
            Save
          </Button>
        </DialogActions>
      </Dialog>
    </Container>
  );
}
