import {
  Box,
  Card,
  CardContent,
  CardMedia,
  Container,
  Grid,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography
} from '@mui/material';
import { styled } from '@mui/material/styles';
import { collection, getDocs, getFirestore } from 'firebase/firestore';
import { useEffect, useState } from 'react';

const CardStyled = styled(Card)(({ theme }) => ({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  padding: theme.spacing(2),
}));

export default function Home() {
  const [students, setStudents] = useState([]);
  const [teachers, setTeachers] = useState([]);
  const [classCounts, setClassCounts] = useState({});

  useEffect(() => {
    const fetchData = async () => {
      const db = getFirestore();

      // Fetch students
      const studentsSnapshot = await getDocs(collection(db, 'Students'));
      const studentsData = studentsSnapshot.docs.map(doc => doc.data());
      setStudents(studentsData);

      // Fetch teachers
      const teachersSnapshot = await getDocs(collection(db, 'Teachers'));
      const teachersData = teachersSnapshot.docs.map(doc => doc.data());
      setTeachers(teachersData);

      // Calculate class counts
      const classCounts = studentsData.reduce((acc, student) => {
        const { classLevel } = student;
        if (!acc[classLevel]) {
          acc[classLevel] = { male: 0, female: 0, total: 0 };
        }
        acc[classLevel].total += 1;
        if (student.sex === 'Male') {
          acc[classLevel].male += 1;
        } else if (student.sex === 'Female') {
          acc[classLevel].female += 1;
        }
        return acc;
      }, {});

      setClassCounts(classCounts);
    };

    fetchData();
  }, []);

  const totalStudents = students.length;
  const totalTeachers = teachers.length;

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Grid container spacing={3}>
        {/* Cards */}
        {[
          { label: 'Students', value: totalStudents },
          { label: 'Teachers', value: totalTeachers }
        ].map((card, index) => (
          <Grid item xs={12} md={6} key={index}>
            <CardStyled>
              <CardMedia
                component="img"
                height="140"
                image="https://via.placeholder.com/150"
                alt={card.label}
              />
              <CardContent>
                <Typography variant="h4">{card.label}</Typography>
                <Typography variant="h6">{card.value}</Typography>
              </CardContent>
            </CardStyled>
          </Grid>
        ))}
      </Grid>

      {/* Table */}
      <Box sx={{ mt: 4 }}>
        <Paper>
          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Class</TableCell>
                  <TableCell align="right">Male</TableCell>
                  <TableCell align="right">Female</TableCell>
                  <TableCell align="right">Total</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {Object.keys(classCounts).map((className) => (
                  <TableRow key={className}>
                    <TableCell component="th" scope="row">
                      {className}
                    </TableCell>
                    <TableCell align="right">{classCounts[className].male}</TableCell>
                    <TableCell align="right">{classCounts[className].female}</TableCell>
                    <TableCell align="right">{classCounts[className].total}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
      </Box>
    </Container>
  );
}
