import { Box, Button, Container, Typography } from '@mui/material';
import * as React from 'react';
import { useLocation, useParams } from 'react-router-dom';

export default function StudentDetail() {
  const { className, studentName } = useParams();
  const location = useLocation();
  const student = location.state?.student; // Get student data from location state
    // Helper function to calculate age
    const calculateAge = (dob) => {
      const birthDate = new Date(dob);
      const today = new Date();
      let age = today.getFullYear() - birthDate.getFullYear();
      const monthDifference = today.getMonth() - birthDate.getMonth();
  
      if (monthDifference < 0 || (monthDifference === 0 && today.getDate() < birthDate.getDate())) {
        age--;
      }
      return age;
    }

  if (!student) {
    return (
      <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
        <Typography variant="h4">Student Details</Typography>
        <Typography variant="body1">No student data available.</Typography>
      </Container>
    );
  }

  return (
    <Container maxWidth="md" sx={{ mt: 4, mb: 4 }}>
      <Box sx={{ textAlign: 'center', mb: 4 }}>
        <img
          src={student.image}
          alt={student.name}
          style={{
            width: 150,
            height: 150,
            borderRadius: '50%',
            marginBottom: '16px',
            border: '2px solid #ccc',
          }}
        />
        <Typography variant="h4" gutterBottom>
          {student.name}
        </Typography>
      </Box>
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          gap: 2,
          textAlign: 'left',
        }}
      >
        <Typography variant="h6">Age: {calculateAge(student.dob)}</Typography>
        <Typography variant="body1">Date of Birth: {new Date(student.dob).toLocaleDateString()}</Typography>
        <Typography variant="body1">Sex: {student.sex}</Typography>
        <Typography variant="body1">Address: {student.address}</Typography>
        <Typography variant="body1">Parent/Guardian: {student.parentName}</Typography>
        <Typography variant="body1">Contact: {student.contact}</Typography>
        <Typography variant="body1">Religious Affiliation: {student.religiousAffiliation}</Typography>
        <Typography variant="body1">Date of Admission: {new Date(student.dateOfAdmission).toLocaleDateString()}</Typography>
      </Box>
      <Box sx={{ textAlign: 'center', mt: 4 }}>
        <Button variant="contained" color="primary">
          Print
        </Button>
      </Box>
    </Container>
  );
}
