import { Visibility, VisibilityOff } from '@mui/icons-material';
import { Box, Button, CircularProgress, FormControl, IconButton, InputAdornment, InputLabel, OutlinedInput, Paper, TextField, Typography } from '@mui/material';
import { getAuth, signInWithEmailAndPassword } from 'firebase/auth';
import { collection, getDocs, getFirestore, query, where } from 'firebase/firestore';
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import '../App.css'; // Ensure this file includes your custom styles
import logo from '../assets/images/log.png'; // Replace with your logo path


export default function SignIn() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false); // Loading state
  const auth = getAuth();
  const navigate = useNavigate();
  const firestore = getFirestore();
 
  

  const handleTogglePassword = () => {
    setShowPassword(!showPassword);
  };

  const handleLogin = async () => {
    setLoading(true); // Start loading
    setError(''); // Clear previous errors
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const user = userCredential.user;
      console.log('User authenticated:', user.uid);

      // Check user's role
      const adminQuery = query(collection(firestore, "Admin"), where("id", "==", user.uid));
      const teacherQuery = query(collection(firestore, "Teachers"), where("id", "==", user.uid));

      const adminSnapshot = await getDocs(adminQuery);
      const teacherSnapshot = await getDocs(teacherQuery);

      if (!adminSnapshot.empty) {
        console.log('User is an admin');
        navigate('/admin');
      } else if (!teacherSnapshot.empty) {
        console.log('User is a teacher');
        navigate('/teacher');
      } else {
        console.log('User role not recognized');
        setError('User role not recognized.');
      }
    } catch (err) {
      console.error('Login error:', err);
      let errorMessage = 'An error occurred. Please try again.';
      
      if (err.code === 'auth/invalid-email') {
        errorMessage = 'Invalid email address.';
      } else if (err.code === 'auth/user-disabled') {
        errorMessage = 'This account has been disabled.';
      } else if (err.code === 'auth/user-not-found') {
        errorMessage = 'No account found with this email.';
      } else if (err.code === 'auth/wrong-password') {
        errorMessage = 'Incorrect password.';
      }
      
      setError(errorMessage);
    } finally {
      setLoading(false); // Stop loading
    }
  };

  const handleForgotPassword = () => {
    // Handle forgot password functionality here
    navigate('/forgot-password')
  };

  return (
    <div className="container-fluid p-0">
      <div className="row no-gutters">
        <div className="col-md-6 con">
          <div style={{ height: '100vh', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center' }}>
            <Typography variant="h3" sx={{ color: 'white', fontWeight: 'bold', mb: 2 }}>
              School Management System
            </Typography>
            <Typography variant="h4" sx={{ color: 'white' }}>
              Hohoe E.P Basic School "A"
            </Typography>
          </div>
        </div>
        <div className="col-md-6 d-flex justify-content-center align-items-center">
          <Box sx={{ width: '100%', maxWidth: '400px' }}>
            <img src={logo} alt="Logo" style={{ width: '150px', marginBottom: '20px', display: 'block', marginLeft: 'auto', marginRight: 'auto' }} />
            <Paper elevation={3} sx={{ p: 4, width: '100%' }}>
              <Typography variant="h5" sx={{ mb: 4, textAlign: 'center' }}>
                Sign In
              </Typography>
              {error && <Typography color="error" sx={{ mb: 2, textAlign: 'center' }}>{error}</Typography>}
              <FormControl fullWidth sx={{ mb: 2 }}>
                <TextField
                  label="Email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  variant="outlined"
                  disabled={loading} // Disable input while loading
                />
              </FormControl>
              <FormControl fullWidth variant="outlined" sx={{ mb: 2 }}>
                <InputLabel htmlFor="outlined-adornment-password">Password</InputLabel>
                <OutlinedInput
                  id="outlined-adornment-password"
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  endAdornment={
                    <InputAdornment position="end">
                      <IconButton
                        aria-label="toggle password visibility"
                        onClick={handleTogglePassword}
                        edge="end"
                      >
                        {showPassword ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  }
                  label="Password"
                  disabled={loading} // Disable input while loading
                />
              </FormControl>
              {loading ? (
                <Box sx={{ textAlign: 'center', mt: 2 }}>
                  <CircularProgress />
                </Box>
              ) : (
                <>
                  <Button variant="contained" color="primary" fullWidth sx={{ mb: 2 }} onClick={handleLogin}>
                    Login
                  </Button>
                  <Button color="primary" onClick={handleForgotPassword} sx={{ textTransform: 'none' }}>
                    Forgot Password?
                  </Button>
                </>
              )}
            </Paper>
          </Box>
        </div>
      </div>
    </div>
  );
}
