import {
  Autocomplete,
  Avatar,
  Box,
  Button,
  Checkbox,
  CircularProgress,
  Container,
  FormControlLabel,
  TextField,
  Typography
} from '@mui/material';
import { createUserWithEmailAndPassword, getAuth } from 'firebase/auth';
import { addDoc, collection, getDocs, getFirestore, query, where } from 'firebase/firestore';
import { getDownloadURL, getStorage, ref, uploadBytesResumable } from 'firebase/storage';
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

// Sample data for classes and subjects
const classesOptions = ['KG 1', 'KG 2', 'Basic 1', 'Basic 2', 'Basic 3', 'Basic 4', 'Basic 5', 'Basic 6', 'Basic 7', 'Basic 8', 'Basic 9'];
const subjectsOptions =['Mathematics','Literacy','Language','RME', 'Integrated Science','Numeracy', 'English Language', 'History', 'Creative Art', 'Owop', 'French', 'Ewe', 'Career Tech.', 'Social Studies', 'Computing'];

export default function AddTeacher() {
  const navigate = useNavigate();
  const [classes, setClasses] = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [isClassTeacher, setisClassTeacher] = useState(false);
  const [classTeacher, setclassTeacher] = useState('');
  const [image, setImage] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  const auth = getAuth();
  const firestore = getFirestore();
  const storage = getStorage();

  const checkStaffIdExists = async (staffId) => {
    const teachersRef = collection(firestore, 'Teachers');
    const q = query(teachersRef, where('staffId', '==', staffId));
    const querySnapshot = await getDocs(q);
    return !querySnapshot.empty; // Returns true if staffId exists, otherwise false
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setLoading(true);

    const formData = new FormData(event.target);
    const name = formData.get('name');
    const staffId = formData.get('staffId');
    const email = formData.get('email');
    const password = formData.get('password');

    try {
      // Check if the staff ID already exists
      const staffIdExists = await checkStaffIdExists(staffId);
      if (staffIdExists) {
        setError('A teacher with this Staff ID already exists.');
        setLoading(false);
        return;
      }

      // Create user with email and password
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      const user = userCredential.user;

      let imageUrl = '';

      // Upload image if selected
      if (image) {
        const storageRef = ref(storage, `profilePictures/${user.uid}`);
        const uploadTask = uploadBytesResumable(storageRef, image);

        await new Promise((resolve, reject) => {
          uploadTask.on(
            'state_changed',
            null,
            (error) => {
              console.error('Error uploading image:', error);
              reject(error);
            },
            async () => {
              imageUrl = await getDownloadURL(uploadTask.snapshot.ref);
              resolve();
            }
          );
        });
      }

      // Add teacher details to Firestore
      await addDoc(collection(firestore, 'Teachers'), {
        id: user.uid,
        name,
        staffId,
        email,
        classes,
        subjects,
        role: "teacher",
        isClassTeacher,
        classTeacher, // Store the class the teacher will be a class teacher for, if applicable
        image: imageUrl // Store the image URL
      });

      console.log('Teacher added:', { name, staffId, email, classes, subjects, isClassTeacher, classTeacher, imageUrl });
      setSuccess(true);
      setTimeout(() => navigate(-1), 1000); // Navigate back to the teachers list after 1 second
    } catch (err) {
      console.error('Error adding teacher:', err);
      setError('An error occurred. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleImageChange = (event) => {
    const file = event.target.files[0];
    if (file) {
      setImage(file);
      const reader = new FileReader();
      reader.onload = () => {
        setImagePreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <Container maxWidth="md" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Add New Teacher
      </Typography>
      <form onSubmit={handleSubmit}>
        {imagePreview && (
          <Box sx={{ display: 'flex', justifyContent: 'center', mb: 2 }}>
            <Avatar src={imagePreview} alt="Image Preview" sx={{ width: 100, height: 100 }} />
          </Box>
        )}
        <input
          accept="image/*"
          style={{ display: 'none' }}
          id="image-upload"
          type="file"
          onChange={handleImageChange}
        />
        <label htmlFor="image-upload">
          <Button variant="contained" color="primary" component="span">
            Upload Image
          </Button>
        </label>
        <TextField
          required
          fullWidth
          label="Name"
          margin="normal"
          variant="outlined"
          name="name"
        />
        <TextField
          required
          fullWidth
          label="Staff ID"
          margin="normal"
          variant="outlined"
          name="staffId"
        />
        <TextField
          required
          fullWidth
          label="Email"
          margin="normal"
          variant="outlined"
          name="email"
          type="email"
        />
        <TextField
          required
          fullWidth
          label="Password"
          margin="normal"
          variant="outlined"
          name="password"
          type="password"
        />
        <Autocomplete
          multiple
          options={classesOptions}
          getOptionLabel={(option) => option}
          value={classes}
          onChange={(event, newValue) => setClasses(newValue)}
          renderInput={(params) => (
            <TextField
              {...params}
              variant="outlined"
              label="Classes"
              margin="normal"
              placeholder="Select classes"
            />
          )}
        />
        <Autocomplete
          multiple
          options={subjectsOptions}
          getOptionLabel={(option) => option}
          value={subjects}
          onChange={(event, newValue) => setSubjects(newValue)}
          renderInput={(params) => (
            <TextField
              {...params}
              variant="outlined"
              label="Subjects"
              margin="normal"
              placeholder="Select subjects"
            />
          )}
        />
        <FormControlLabel
          control={
            <Checkbox
              checked={isClassTeacher}
              onChange={(event) => setisClassTeacher(event.target.checked)}
            />
          }
          label="Class Teacher"
        />
        {isClassTeacher && (
          <Autocomplete
            options={classesOptions}
            getOptionLabel={(option) => option}
            value={classTeacher}
            onChange={(event, newValue) => setclassTeacher(newValue)}
            renderInput={(params) => (
              <TextField
                {...params}
                variant="outlined"
                label="Class for Teacher"
                margin="normal"
                placeholder="Select one class"
              />
            )}
          />
        )}
        {error && <Typography color="error" sx={{ mt: 2 }}>{error}</Typography>}
        {loading && (
          <Box sx={{ display: 'flex', justifyContent: 'center', mt: 2 }}>
            <CircularProgress />
          </Box>
        )}
        {!loading && !success && (
          <Box sx={{ mt: 2, display: 'flex', justifyContent: 'space-between' }}>
            <Button variant="contained" color="primary" type="submit">
              Add Teacher
            </Button>
            <Button variant="outlined" color="secondary" onClick={() => navigate(-1)}>
              Cancel
            </Button>
          </Box>
        )}
        {success && (
          <Typography color="primary" sx={{ mt: 2, textAlign: 'center' }}>
            Teacher added successfully! Redirecting...
          </Typography>
        )}
      </form>
    </Container>
  );
}
